// Limpieza del texto para WhatsApp
return items.map(item => {
  let msg = item.json.mensaje || "";

  // 1️⃣ Sustituir saltos de línea escapados (\n → salto real)
  msg = msg.replace(/\\n/g, '\n');

  // 2️⃣ Convertir negritas de doble asterisco a una sola (*texto*)
  msg = msg.replace(/\*\*(.*?)\*\*/g, '*$1*');

  // 3️⃣ Eliminar comillas escapadas (\" → ")
  msg = msg.replace(/\\"/g, '"');

  // 4️⃣ Corregir dobles backslashes (\\ → \)
  msg = msg.replace(/\\\\/g, '\\');

  // 5️⃣ Limpiar espacios innecesarios al inicio y fin
  msg = msg.trim();

  // 6️⃣ Actualizar el valor limpio
  item.json.mensaje_limpio = msg;

  return item;
});
